import cn from 'classnames';
import { TableOfContentChild, TableOfContentProps } from './table-of-content.types';

export const TableOfContent = ({
  id,
  listType,
  ignoreClasses,
  className,
  items
}: TableOfContentProps) => {

  const ListType = ({ children }) => listType === 'bulleted' ? <ul>{children}</ul> : <ol>{children}</ol>

  const TableOfContentItem = ({ children, text, href }: TableOfContentChild) => {
    return (
      <li>
        <a href={href}>{text}</a>
        {children.length ? <ListType>{children.map((item, index) => <TableOfContentItem {...item} key={index} />)}</ListType> : null}
      </li>
    )
  }

  return (
    <div className={cn('tableofcontents', className)}>
      <div className="cmp-toc__content" id={id}>
        <ListType>
          {items.length && items.map((item, index) => <TableOfContentItem {...item} key={index} />)}
        </ListType>
      </div>
    </div>
  );
}

export default TableOfContent;
